options.onOperationButtonClick:
const todoId = row['id']
const stationType = row['stationType'];
const deviceNo = row['deviceNo'];
const deviceName = row['name'];
this.getFormRef().globalDsv.id = todoId
if(buttonName==='edit')
{
  this.getFormRef().executeDataSource('detail').then(res=>{
    this.getFormRef().showDialog('AddOrUpdateDialog',res,{editFlag:'edit'});
  })
}
else if(buttonName==='delete')
{
  this.$confirm('此操作将永久删除该条信息, 是否继续?', '提示',{
    confirmButtonText: '确定',
      cancelButtonText: '取消',
      type: 'warning'
  }).then(() => {
      this.getFormRef().executeDataSource('delete').then(res=>{
      this.$message.success("删除成功！")

      var tree = this.getWidgetRef("preTree",false).getNativeTree();
      var typeId = tree.currentNode.data.id;

      let dt=this.getFormRef().getWidgetRef('dtBusiness',false);
      dt.loadDataFromDS({'stationType':typeId},'list');//loadDataFromDS 从数据源加载表格数据

      }).catch(error=>{
        this.$message.success("删除失败！")
      })
    }).catch(() => {
      this.$message({
        type: 'info',
        message: '已取消删除'
      });
    });
}
else if(buttonName==='control')
{
  if(stationType == 50)//提撑挤压工位
  {
    //alert('提撑挤压工位');
    this.getFormRef().showDialog('dialog_LiftStation',null,{deviceName:deviceName,deviceNo:deviceNo});
  }
  else if(stationType == 80)//包装翻倒工位
  {
    //alert('包装翻倒工位');
    this.getFormRef().showDialog('dialog_PackOverturnStation',null,{deviceName:deviceName,deviceNo:deviceNo});
  }
  else if(stationType == 90)//脏桶回流工位
  {
    //alert('脏桶回流工位');
    this.getFormRef().showDialog('dialog_DirtyRefluxStation',null,{deviceName:deviceName,deviceNo:deviceNo});
  }
  else if(stationType == 40)
  {
    var roadway = row['roadway'];
    window.location.href = "#/onlineDev/rgvControlTools?deviceNo="+deviceNo+"&deviceName="+encodeURIComponent(deviceName)+"&roadwayNo="+roadway+"";
  }
  else
  {
    this.$message.warning('该工位暂时没有控制功能');
  }
}
else if(buttonName==='viewbucket')
{
  let roadwayNo = row['roadway'];
  this.getFormRef().globalDsv.roadwayNo = roadwayNo

  this.getFormRef().executeDataSource('getContainers').then(res=>{
    let message = "";
    if(res == "")
    {
      message = "二煎空桶缓存区不存在桶记录！";
    }
    else
    {
      message = "当前缓存区桶号："+res;
    }

    this.$alert(message, '', {
          confirmButtonText: '关闭',
          callback: action => {}
        });

  })
}
else
{}

