options.onDialogOpened:
const extraData = this.getExtraData();//获取外部带入数据对象（打开弹窗时通过打开弹窗事件带入的参数）
const deviceName = extraData.deviceName;
const deviceNo = extraData.deviceNo;
this.getWidgetRef('txtNo',false).setValue(deviceNo);
this.getWidgetRef('txtName',false).setValue(deviceName);

var singlar = this.getFormRef().globalDsv.signalR;

//取消监听
singlar.off("PublicLiftCompleteMessage");
singlar.off("PublicLiftVolumeReachMessage");
singlar.off("PublicLiftBucketReachMessage");

//监听事件
singlar.on("PublicLiftCompleteMessage", (para, msg) => {
  if(para != null && para != undefined && para.deviceNo == deviceNo)
  {
    const now = new Date();
    const formattedDate = now.toLocaleString();
	
	var oldStr = this.getWidgetRef('txtMessage',false).getValue();
	var newStr = "收到了沥液完成事件,桶号："+para.containerNo+'，时间：'+ formattedDate;
	var message = "";
	if(oldStr == "" || oldStr == undefined || oldStr == null)
	{
		message = newStr;
	}
	else
	{
		message = oldStr + "\n" + newStr;
	}
    this.getWidgetRef('txtMessage',false).setValue(message);
  }
});

singlar.on("PublicLiftVolumeReachMessage", (para, msg) => {
    if(para != null && para != undefined && para.deviceNo == deviceNo)
  {
    const now = new Date();
    const formattedDate = now.toLocaleString();
	
	var oldStr = this.getWidgetRef('txtMessage',false).getValue();
	var newStr = "沥液工位上传体积,得液量："+para.volumnAmount+'，时间：'+ formattedDate;
	var message = "";
	if(oldStr == "" || oldStr == undefined || oldStr == null)
	{
		message = newStr;
	}
	else
	{
		message = oldStr + "\n" + newStr;
	}
    this.getWidgetRef('txtMessage',false).setValue(message);
  }
});

singlar.on("PublicLiftBucketReachMessage", (para, msg) => {  
  if(para != null && para != undefined && para.deviceNo == deviceNo)
  {
    const now = new Date();
    const formattedDate = now.toLocaleString();
	
	var oldStr = this.getWidgetRef('txtMessage',false).getValue();
	var newStr = "沥液工位桶到,桶号："+para.containerNo+'，时间：'+ formattedDate;
	var message = "";
	if(oldStr == "" || oldStr == undefined || oldStr == null)
	{
		message = newStr;
	}
	else
	{
		message = oldStr + "\n" + newStr;
	}
    this.getWidgetRef('txtMessage',false).setValue(message);
    this.getWidgetRef('txtContainerNo',false).setValue(para.containerNo);
  }
});

